	ch, err := svc.Execute(context.Background(), ServiceExecuteRequest{
		Prompt:   "hello",
		Harness:  "agent",
		Provider: "openrouter",
		Model:    "gpt-5.4",
	})
	if err != nil {
		t.Fatalf("Execute: unexpected synchronous error: %v", err)
